@@ -31,9 +31,9 @@
 const inv={wood:20,stone:8,meat:3};
 addEventListener('keydown',e=>{keys[e.key.toLower]=true;keys[e.key.toLowerCase()]=true;if(e.key===' '||e.key==='e')interact()});addEventListener('keyup',e=>{keys[e.key.toLower]=false;keys[e.key.toLowerCase()]=false});
 function toast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(el.t);el.t=setTimeout(()=>el.classList.remove('show'),1200)}
 function interact(){if(!running)return;let nearest=null,dist=55;for(const t of trees){let d=Math.hypot(t.x-player.x,t.y-player.y);if(d<dist){dist=d;nearest=t}}if(nearest){nearest.hp--;inv.wood+=1;toast('Axe: +1 wood');if(nearest.hp<=0){nearest.dead=true;trees=trees.filter(t=>!t.dead)}return}for(const r of rocks){let d=Math.hypot(r.x-player.x,r.y-player.y);if(d<dist){dist=d;nearest=r}}if(nearest){nearest.hp--;inv.stone+=1;toast('Pickaxe: +1 stone');if(nearest.hp<=0)nearest.dead=true;rocks=rocks.filter(r=>!r.dead);return}if(Math.hypot(player.x-camp.x,player.y-camp.y)<90){if(inv.wood>=3){inv.wood-=3;camp.fire=Math.min(100,camp.fire+25);toast('Fire restored')}else toast('Need 3 wood')}updateUI()}
-const ia=document.getElementById('interact');ia.addEventListener('pointerdown',e=>{e.prevent.;interact()});
+const ia=document.getElementById('interact');ia.addEventListener('pointerdown',e=>{e.preventDefault();interact()});
 const stick=document.getElementById('stick'),knob=document.getElementById('knob');let active=false;
 stick.addEventListener('pointerdown',e=>{active=true;stick.setPointerCapture(e.pointerId)});stick.addEventListener('pointermove',e=>{if(!active)return;let r=stick.getBoundingRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,x=e.clientX-cx,y=e.clientY-cy,l=Math.hypot(x,y),m=38;if(l>m){x=x/l*m;y=y/l*m}knob.style.transform=`translate(${x}px,${y}px)`;joystick.x=x/m;joystick.y=y/m});function release(){active=false;joystick.x=0;joystick.y=0;knob.style.transform=''}stick.addEventListener('pointerup',release);stick.addEventListener('pointercancel',release);
 function updateUI(){document.getElementById('wood').textContent=inv.wood;document.getElementById('stone').textContent=inv.stone;document.getElementById('meat').textContent=inv.meat;document.getElementById('hp').style.width=Math.max(0,hp)+'%';document.getElementById('hpText').textContent=Math.ceil(hp)}
 function worldToScreen(x,y){return{x:W/2+(x-player.x),y:H/2+(y-player.y)}}

