 <div class="start gameover" id="gameover"><div class="card panel"><h1>THE FOREST WON<span id="endTitle">NIGHT 1</span></h1><p id="endText">The fire went out...</p><button id="again">TRY AGAIN</button></div></div>
 <script>
 const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),map=document.getElementById('map'),mctx=map.getContext('2d');let W,H,DPR;
-function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize;
+function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);
 resize();
 let running=false,gameOver=false,last=0,day=1,time=270,hp=100,score=0;const player={x:0,y:0,r:12,angle:0,inv:0};let keys={},joystick={x:0,y:0},trees=[],rocks=[],animals=[],camp={x:0,y:0,fire:100};
 function rand(a,b){return a+Math.random*(b-a)}
 function seedWorld(){trees=[];rocks=[];animals=[];for(let i=0;i<260;i++){let a=Math.random()*Math.PI*2,d=180+Math.random()*1100,x=Math.cos(a)*d,y=Math.sin(a)*d;if(Math.hypot(x,y)<150)continue;trees.push({x,y,s:.75+Math.random*.7,hp:2})}for(let i=0;i<55;i++){let a=Math.random()*6.28,d=220+Math.random()*900;rocks.push({x:Math.cos(a)*d,y:Math.sin(a)*d,hp:2})}for(let i=0;i<12;i++){let a=Math.random()*6.28,d=300+Math.random()*700;animals.push({x:Math.cos(a)*d,y:Math.sin(a)*d,type:Math.random()<.35?'wolf':'deer',phase:Math.random()*6})}}
